import pytest
import torch

from . import base


# torch.special.bessel_y0 only supports float32/float64 on all backends,
# so we benchmark float32 only.
@pytest.mark.special_bessel_y0
def test_special_bessel_y0():
    def special_bessel_y0_input_fn(shape, dtype, device):
        # y0 is only defined for x > 0, so the positive domain is sampled instead
        # of the default randn input which would be half out of domain.
        yield torch.empty(shape, dtype=dtype, device=device).uniform_(0.1, 20.0),

    bench = base.GenericBenchmark(
        input_fn=special_bessel_y0_input_fn,
        op_name="special_bessel_y0",
        torch_op=torch.special.bessel_y0,
        dtypes=[torch.float32],
    )
    bench.run()
